  for(const group of groups.values()){const target=lineCost(group.unitCost,group.units),floor=group.entries.reduce((n,x)=>n+x.entry.cost,0),residue=target-floor;group.entries.sort((a,b)=>b.remainder-a.remainder||a.index-b.index);for(let i=0;i<residue;i++)group.entries[i].entry.cost++;}
